--- src/app/contexts/UserContext/cookies/index.js
import Cookie from 'js-cookie';
import { getVariantCookieName } from '#lib/utilities/variantHandler';
import setCookie from '#lib/utilities/setCookie';

export const getCookiePolicy = () => {
  const POLICY_COOKIE = 'ckns_policy';

  return Cookie.get(POLICY_COOKIE) || '000';
};

export const personalisationEnabled = cookiePolicy =>
  cookiePolicy && cookiePolicy.length === 3 && cookiePolicy[2] === '1';

export const getPreferredVariant = service => {
  if (!service) return null;
  const VARIANT_COOKIE = `ckps_${getVariantCookieName(service)}`;

  return Cookie.get(VARIANT_COOKIE);
};

export const setPreferredVariantCookie = (service, variant) => {
  if (!service || !variant || !personalisationEnabled(getCookiePolicy())) {
    return;
  }

  const variantCookieName = `ckps_${getVariantCookieName(service)}`;
  const COOKIE_EXPIRY = 7;

  // Setting variant cookie to have sameSite=Lax because the purpose of this
  // cookie is to only be used in a first-party context and make sure the page
  // is rendered correctly on initial load when arrived from external source.
  setCookie({
    name: variantCookieName,
    value: variant,
    expires: COOKIE_EXPIRY,
    sameSite: 'Lax',
  });
};
--- src/app/containers/ChartbeatAnalytics/utils/index.js
import Cookie from 'js-cookie';
import path from 'ramda/src/path';
import pathOr from 'ramda/src/pathOr';
import onClient from '#lib/utilities/onClient';
import { getPromoHeadline } from '#lib/analyticsUtils/article';
import { getPageTitle } from '#lib/analyticsUtils/indexPage';
import { getReferrer } from '#lib/analyticsUtils';
import {
  ARTICLE_PAGE,
  FRONT_PAGE,
  MEDIA_PAGE,
  MOST_READ_PAGE,
  MOST_WATCHED_PAGE,
  INDEX_PAGE,
  FEATURE_INDEX_PAGE,
  MEDIA_ASSET_PAGE,
  PHOTO_GALLERY_PAGE,
  STORY_PAGE,
} from '#app/routes/utils/pageTypes';

const ID_COOKIE = 'ckns_sylphid';

export const chartbeatUID = 50924;
export const useCanonical = true;
export const chartbeatSource = '//static.chartbeat.com/js/chartbeat.js';

const buildSectionArr = (service, value, type) => [
  `${service} - ${value}`,
  ...(type ? [`${service} - ${value} - ${type}`] : []),
];

const buildSectionItem = (service, type) => [`${service} - ${type}`];

const capitalize = s => s.charAt(0).toUpperCase() + s.slice(1);

export const getSylphidCookie = () =>
  onClient() ? Cookie.get(ID_COOKIE) : null;

export const getType = (pageType, shorthand = false) => {
  switch (pageType) {
    case FRONT_PAGE:
    case INDEX_PAGE:
    case 'index':
      return shorthand ? INDEX_PAGE : 'Index';
    case ARTICLE_PAGE:
      return shorthand ? 'ART' : 'New Article';
    case MEDIA_ASSET_PAGE:
      return 'article-media-asset';
    case MEDIA_PAGE:
      return 'Radio';
    case MOST_READ_PAGE:
      return 'Most Read';
    case MOST_WATCHED_PAGE:
      return 'Most Watched';
    case STORY_PAGE:
      return STORY_PAGE;
    case PHOTO_GALLERY_PAGE:
      return PHOTO_GALLERY_PAGE;
    case FEATURE_INDEX_PAGE:
      return FEATURE_INDEX_PAGE;
    default:
      return null;
  }
};

export const buildSections = ({
  service,
  pageType,
  producer,
  chapter,
  sectionName,
  categoryName,
  mediaPageType,
}) => {
  const addProducer = producer && service !== producer;
  const serviceCap = capitalize(service);
  const type = getType(pageType, true);
  const appendCategory = name => `${name}-category`;

  const mediaSectionLabel = {
    'On Demand Radio': 'Radio',
    'Live Radio': 'Radio',
    'On Demand TV': 'TV',
    Podcast: 'Podcasts',
  };

  switch (pageType) {
    case MEDIA_ASSET_PAGE:
      return [
        serviceCap,
        buildSectionItem(serviceCap, sectionName),
        buildSectionItem(serviceCap, pageType),
        buildSectionItem(buildSectionItem(serviceCap, sectionName), pageType),
        buildSectionItem(serviceCap, appendCategory(categoryName)),
      ].join(', ');
    case MEDIA_PAGE:
      return [
        serviceCap,
        ...(pageType
          ? buildSectionItem(serviceCap, mediaSectionLabel[mediaPageType])
          : []),
        ...(addProducer ? buildSectionArr(serviceCap, producer, type) : []),
        ...(chapter ? buildSectionArr(serviceCap, chapter, type) : []),
      ].join(', ');
    case STORY_PAGE:
      return [
        serviceCap,
        buildSectionItem(serviceCap, sectionName),
        buildSectionItem(serviceCap, pageType),
        buildSectionItem(buildSectionItem(serviceCap, sectionName), pageType),
        buildSectionItem(serviceCap, appendCategory(categoryName)),
      ].join(', ');
    default:
      return [
        serviceCap,
        ...(pageType ? buildSectionItem(serviceCap, type) : []),
        ...(addProducer ? buildSectionArr(serviceCap, producer, type) : []),
        ...(chapter ? buildSectionArr(serviceCap, chapter, type) : []),
      ].join(', ');
  }
};

export const getTitle = ({ pageType, pageData, brandName, title }) => {
  switch (pageType) {
    case FRONT_PAGE:
    case INDEX_PAGE:
    case 'index':
      return getPageTitle(pageData, brandName);
    case ARTICLE_PAGE:
      return getPromoHeadline(pageData);
    case MEDIA_ASSET_PAGE:
      return path(['promo', 'headlines', 'headline'], pageData);
    case MEDIA_PAGE:
      return path(['pageTitle'], pageData);
    case MOST_READ_PAGE:
      return `${title} - ${brandName}`;
    case MOST_WATCHED_PAGE:
      return `${title} - ${brandName}`;
    case STORY_PAGE:
      return path(['promo', 'headlines', 'headline'], pageData);
    case PHOTO_GALLERY_PAGE:
      return path(['promo', 'headlines', 'headline'], pageData);
    case FEATURE_INDEX_PAGE:
      return getPageTitle(pageData, brandName);
    default:
      return null;
  }
};

const getTvRadioContentType = path(['contentType']);

export const getConfig = ({
  isAmp,
  platform,
  pageType,
  data,
  brandName,
  env,
  service,
  origin,
  previousPath,
  chartbeatDomain,
  mostReadTitle,
  mostWatchedTitle,
}) => {
  const referrer =
    previousPath || isAmp ? getReferrer(platform, origin, previousPath) : null;

  const title = getTitle({
    pageType,
    pageData: data,
    brandName,
    title: pageType === MOST_WATCHED_PAGE ? mostWatchedTitle : mostReadTitle,
  });
  const domain = env !== 'live' ? 'test.bbc.co.uk' : chartbeatDomain;
  const sectionName = path(['relatedContent', 'section', 'name'], data);
  const categoryName = path(
    ['metadata', 'passport', 'category', 'categoryName'],
    data,
  );

  const mediaPageType = pathOr('', ['metadata', 'type'], data);

  const sections = buildSections({
    service,
    pageType,
    sectionName,
    categoryName,
    mediaPageType,
  });
  const cookie = getSylphidCookie();
  const type = getType(pageType);
  const contentType =
    pageType === MEDIA_PAGE ? getTvRadioContentType(data) : type;
  const currentPath = onClient() && window.location.pathname;
  return {
    domain,
    sections,
    uid: chartbeatUID,
    title,
    virtualReferrer: referrer,
    ...(isAmp && { contentType }),
    ...(!isAmp && {
      type: contentType,
      useCanonical,
      path: currentPath,
    }),
    ...(cookie && { idSync: { bbc_hid: cookie } }),
  };
};
--- src/app/containers/ConsentBanner/CanonicalLogic/index.js
import Cookie from 'js-cookie';
import setCookie from '#lib/utilities/setCookie';
import setCookieOven from './setCookieOven';

const PRIVACY_COOKIE = 'ckns_privacy';
const EXPLICIT_COOKIE = 'ckns_explicit';
const POLICY_COOKIE = 'ckns_policy';
const COOKIE_BANNER_APPROVED = '1';
const EXPLICIT_COOKIE_ACCEPTED_VALUES = ['1', '2'];
const POLICY_APPROVED = '111';
const POLICY_DENIED = '000';
const PRIVACY_COOKIE_CURRENT = 'july2019';
const PRIVACY_COOKIE_PREVIOUS_VALUES = ['0', '1'];

const onClient = typeof window !== 'undefined';
const isChromatic = () =>
  process.env.STORYBOOK === 'true' &&
  window.navigator.userAgent.match(/Chromatic/);

// We opted for the sameSite=None attribute below to maintain consistency with Orbit/cross-TLD browsing
// Setting sameSite=None allows the cookie to be accessed and updated on `.co.uk` and `.com`
const SAME_SITE_VALUE = 'None';

const setPolicyCookie = (value, logger) => {
  setCookie({ name: POLICY_COOKIE, value, sameSite: SAME_SITE_VALUE });
  setCookieOven(POLICY_COOKIE, value, logger);
};

const showPrivacyBanner = () => {
  const privacyCookie = Cookie.get(PRIVACY_COOKIE);
  return (
    !privacyCookie || PRIVACY_COOKIE_PREVIOUS_VALUES.includes(privacyCookie)
  );
};
const showCookieBanner = () =>
  !EXPLICIT_COOKIE_ACCEPTED_VALUES.includes(Cookie.get(EXPLICIT_COOKIE));
const policyCookieSet = () => !!Cookie.get(POLICY_COOKIE);

const setSeenPrivacyBanner = () =>
  setCookie({
    name: PRIVACY_COOKIE,
    value: PRIVACY_COOKIE_CURRENT,
    sameSite: SAME_SITE_VALUE,
  });
const setDefaultPolicy = logger => setPolicyCookie(POLICY_DENIED, logger);
const setApprovedPolicy = logger => setPolicyCookie(POLICY_APPROVED, logger);
const setDismissedCookieBanner = () =>
  setCookie({
    name: EXPLICIT_COOKIE,
    value: COOKIE_BANNER_APPROVED,
    sameSite: SAME_SITE_VALUE,
  });

const consentBannerUtilities = ({
  setShowPrivacyBanner,
  setShowCookieBanner,
  logger,
}) => {
  const runInitial = () => {
    if (onClient) {
      if (isChromatic()) {
        // prevent setting cookies so chromatic snapshots are consistent
        setShowPrivacyBanner(true);
        return;
      }

      if (showPrivacyBanner()) {
        setShowPrivacyBanner(true);
        setSeenPrivacyBanner();
      }

      if (showCookieBanner()) {
        // Up to the application renderer to show the privacy
        // banner and cookie banner in the correct order
        setShowCookieBanner(true);
      }

      if (!policyCookieSet()) {
        setDefaultPolicy(logger);
      }
    }
  };

  const privacyOnAllow = () => {
    setShowPrivacyBanner(false);
  };

  const privacyOnReject = () => {
    setShowPrivacyBanner(false);
  };

  const cookieOnAllow = () => {
    setShowCookieBanner(false);
    setDismissedCookieBanner();
    setApprovedPolicy(logger);
  };

  const cookieOnReject = () => {
    setShowCookieBanner(false);
    setDismissedCookieBanner();
  };

  return {
    runInitial,
    privacyOnAllow,
    privacyOnReject,
    cookieOnAllow,
    cookieOnReject,
  };
};

export default consentBannerUtilities;
--- src/app/lib/analyticsUtils/index.js
import Cookie from 'js-cookie';
import { v4 as uuid } from 'uuid';
import pathOr from 'ramda/src/pathOr';
import path from 'ramda/src/path';
import Url from 'url-parse';
import onClient from '../utilities/onClient';
import isOperaProxy from '../utilities/isOperaProxy';
import {
  MEDIUM_CAMPAIGN_IDENTIFIER,
  XTOR_CAMPAIGN_IDENTIFIER,
  SUPPORTED_MEDIUM_CAMPAIGN_TYPES,
} from './analytics.const';
import getAmpDestination from './getAmpDestination';

export const getDestination = (platform, statsDestination) => {
  const destinationIDs = {
    NEWS_PS: 598285,
    NEWS_LANGUAGES_PS: 598291,
    NEWS_GNL: 598287,
    NEWS_LANGUAGES_GNL: 598289,
    NEWS_PS_TEST: 598286,
    NEWS_LANGUAGES_PS_TEST: 598292,
    NEWS_LANGUAGES_GNL_TEST: 598290,
    NEWS_GNL_TEST: 598288,
    WS_NEWS_LANGUAGES: 598342,
    WS_NEWS_LANGUAGES_TEST: 598343,
    PS_HOMEPAGE: 598273,
    PS_HOMEPAGE_TEST: 598274,
    BBC_ARCHIVE_PS: 605565,
    BBC_ARCHIVE_PS_TEST: 605566,
    NEWSROUND: 598293,
    NEWSROUND_TEST: 598294,
    SPORT_GNL: 598308,
    SPORT_GNL_TEST: 598309,
    SPORT_PS: 598310,
    SPORT_PS_TEST: 598311,
  };

  const geoVariants = {
    NEWS_PS: {
      PS: destinationIDs.NEWS_PS,
      GNL: destinationIDs.NEWS_GNL,
    },
    NEWS_PS_TEST: {
      PS: destinationIDs.NEWS_PS_TEST,
      GNL: destinationIDs.NEWS_GNL_TEST,
    },
    SPORT_PS: {
      PS: destinationIDs.SPORT_PS,
      GNL: destinationIDs.SPORT_GNL,
    },
    SPORT_PS_TEST: {
      PS: destinationIDs.SPORT_PS_TEST,
      GNL: destinationIDs.SPORT_GNL_TEST,
    },
    NEWS_LANGUAGES_PS: {
      PS: destinationIDs.NEWS_LANGUAGES_PS,
      GNL: destinationIDs.NEWS_LANGUAGES_GNL,
    },
    NEWS_LANGUAGES_PS_TEST: {
      PS: destinationIDs.NEWS_LANGUAGES_PS_TEST,
      GNL: destinationIDs.NEWS_LANGUAGES_GNL_TEST,
    },
  };

  if (platform === 'amp' && geoVariants[statsDestination]) {
    return getAmpDestination(geoVariants[statsDestination]);
  }

  return destinationIDs[statsDestination] || destinationIDs.NEWS_PS;
};

export const getAppType = platform =>
  platform === 'amp' ? 'amp' : 'responsive';

export const isLocServeCookieSet = platform => {
  if (platform === 'amp') {
    return false;
  }

  if (onClient()) {
    return !!Cookie.get('loc_serve');
  }

  return null;
};

export const getScreenInfo = platform => {
  if (platform === 'amp') {
    return `\${screenWidth}x\${screenHeight}x\${screenColorDepth}`;
  }

  if (onClient()) {
    const { width, height, colorDepth, pixelDepth } = window.screen;
    const orderArray = [
      width || 0,
      height || 0,
      colorDepth || 0,
      pixelDepth || 0,
    ];

    return orderArray.join('x');
  }

  return null;
};

export const getBrowserViewPort = platform => {
  if (platform === 'amp') {
    return `\${availableScreenWidth}x\${availableScreenHeight}`;
  }

  if (onClient()) {
    const { innerWidth, innerHeight } = window;

    return [innerWidth || 0, innerHeight || 0].join('x');
  }

  return null;
};

export const getCurrentTime = platform => {
  if (platform === 'amp') {
    return `\${timestamp}`;
  }

  if (onClient()) {
    const now = new Date();
    const hours = now.getHours();
    const mins = now.getMinutes();
    const secs = now.getSeconds();

    return [hours, mins, secs].join('x');
  }

  return null;
};

export const getDeviceLanguage = platform => {
  if (platform === 'amp') {
    // Using browserlanguage since AMP doesn't have access to device language
    return `\${browserLanguage}`;
  }

  if (onClient() && navigator.language) {
    return navigator.language;
  }

  return null;
};

export const getHref = platform => {
  if (platform === 'amp') {
    return `\${sourceUrl}`;
  }

  if (onClient() && window.location.href) {
    const { href } = window.location;
    return href;
  }

  return null;
};

export const getReferrer = (platform, origin, previousPath) => {
  if (platform === 'amp') {
    /* On AMP, `\${documentReferrer}` is an amp analytics variable that resolves
       to a `document.referrer` equivalent as the window document is undefined on amp pages.
       https://github.com/ampproject/amphtml/blob/master/spec/amp-var-substitutions.md#document-referrer
    */
