  // cookie is to only be used in a first-party context and make sure the page
  // is rendered correctly on initial load when arrived from external source.
  setCookie({
    name: variantCookieName,
    value: variant,
    expires: COOKIE_EXPIRY,
    sameSite: 'Lax',
  });
};
